<script setup lang="tsx">
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import type { BaseTableCol, TableRowData } from "tdesign-vue-next";
import { useCurrentInstance } from "@/util";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import {
  GetBotMatchList,
  GetBotStatusStr,
  GetBotStatusTheme,
  IsBotStatusRunning,
  IsBotMatchTriggeredBySystem,
  BotStatus,
  ParseBotMatch,
} from "@/apis/bot.ts";
import type { BotMatch, BotMatchAgent, BotMatchView } from "@/types/bot.ts";
import type { CellParams } from "@/types/table";
import { GetAvatarUrl } from "@/util/avatar.ts";
import { handleGotoBotGame, handleGotoBotMatch, handleGotoUsername } from "@/util/router";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const dataLoading = ref(false);
const gameKey = ref<string | undefined>(undefined);

// 搜索表单
const searchForm = ref({
  gameKey: "",
});

// 分页信息
const pagination = ref({
  current: 1,
  pageSize: 20,
  defaultCurrent: 1,
  defaultPageSize: 20,
  total: 200,
  pageSizeOptions: [20, 100],
  showPageSize: false,
});

// 对局列表数据
const matchList = ref<BotMatchView[]>([]);

// 表格列配置
const baseListColumns: BaseTableCol<TableRowData>[] = [
  {
    title: "对局ID",
    colKey: "id",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoBotMatch(data.row.gameKey, data.row.id)}>
          {data.row.id}
        </t-button>
      );
    },
  },
  {
    title: "游戏名称",
    colKey: "gameTitle",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return <t-button variant="text" onClick={() => handleGotoBotGame(data.row.gameKey)}>
        {data.row.gameTitle}
      </t-button>;
    },
  },
  {
    title: "状态",
    colKey: "status",
    align: "center",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const status = data.row.status as BotStatus;
      const statusStr = GetBotStatusStr(status);
      const theme = GetBotStatusTheme(status);
      const finalElements = [];
      if (IsBotStatusRunning(status)) {
        finalElements.push(<t-loading text={statusStr} size="small" class="dida-status-loading"></t-loading>);
      } else {
        finalElements.push(<span>{statusStr}</span>);
      }
      return (
        <t-button theme={theme} variant="outline" onClick={() => handleGotoBotMatch(data.row.gameKey, data.row.id)}>
          {finalElements}
        </t-button>
      );
    },
  },
  {
    title: "计算排名",
    colKey: "enableRank",
    align: "center",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-tag theme={data.row.enableRank ? "success" : "danger"}>
          {data.row.enableRank ? "是" : "否"}
        </t-tag>
      );
    },
  },
  {
    title: "玩家列表",
    colKey: "players",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (!data.row.agents || data.row.agents.length === 0) {
        return <span>无</span>;
      }
      return (
        <t-space wrap size="small" class="bot-players-tags">
          {data.row.agents.map((player: BotMatchAgent, index: number) => {
            const rankChange = data.row.ranks?.[index];
            let rankElement = null;
            if (rankChange > 0) {
              rankElement = <span style="color: green; margin-left: 5px">+{rankChange}</span>;
            } else if (rankChange < 0) {
              rankElement = <span style="color: red; margin-left: 5px">{rankChange}</span>;
            }
            return (
              <t-tag key={`${player.id}-${index}`} variant="light">
                {player.name}{rankElement}
              </t-tag>
            );
          })}
        </t-space>
      );
    },
  },
  {
    title: "触发者",
    colKey: "inserter",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      // 系统发起的对局没有对应账号，用标签明示，避免渲染出空白或悬空头像
      if (IsBotMatchTriggeredBySystem(data.row.inserter)) {
        return (
          <t-tag theme="default" variant="light">
            系统
          </t-tag>
        );
      }
      const avatarUrl = GetAvatarUrl(data.row.inserterUsername, data.row.inserterEmail);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button variant="text" onClick={() => handleGotoUsername(router, data.row.inserterUsername)}>
            {data.row.inserterNickname || data.row.inserterUsername}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "提交时间",
    colKey: "insertTime",
    width: 180,
  },
];

// 移动端隐藏"计算排名"列以节省横向空间
const listColumns = computed(() => {
  if (isMobile.value) {
    return baseListColumns.filter((col) => col.colKey !== "enableRank");
  }
  return baseListColumns;
});

// 搜索表单提交
const handleSearchFormSubmit = async () => {
  await router.push({
    query: {
      ...route.query,
      page: 1,
      page_size: pagination.value.pageSize,
      game_key: searchForm.value.gameKey,
    },
  });
};

// 搜索表单重置
const handleSearchFormReset = async () => {
  searchForm.value.gameKey = "";
  await router.push({
    query: {
      ...route.query,
      page: 1,
      page_size: pagination.value.pageSize,
      game_key: "",
    },
  });
};

// 获取对局列表
const fetchData = async (page: number, pageSize: number) => {
  dataLoading.value = true;
  try {
    const res = await GetBotMatchList(gameKey.value, page, pageSize);
    if (res.code === 0) {
      const response = res.data;
      if (response.list && response.list.length > 0) {
        matchList.value = response.list.map((item: BotMatch) => ParseBotMatch(item));
      } else {
        matchList.value = [];
        ShowTextTipsInfo(globalProperties, "未找到记录");
      }
      // 更新分页总数
      if (response.total) {
        pagination.value.total = response.total;
      }
    } else {
      ShowErrorTips(globalProperties, res.code);
      matchList.value = [];
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
    matchList.value = [];
  } finally {
    dataLoading.value = false;
  }
};

// 分页变化处理
const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  await router.push({
    query: { ...route.query, page: pageInfo.current },
  });
};

// 初始化
onMounted(async () => {
  watch(
    () => route.query,
    (newQuery) => {
      gameKey.value = (newQuery.game_key as string) || undefined;
      searchForm.value.gameKey = (newQuery.game_key as string) || "";
      
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      
      pagination.value = { ...pagination.value, current: queryPage, pageSize: queryPageSize };
      fetchData(queryPage, queryPageSize);
    },
    { immediate: true }
  );
});
</script>

<template>
  <t-card style="margin: 10px">
    <t-form :layout="isMobile ? 'default' : 'inline'" @submit="handleSearchFormSubmit" @reset="handleSearchFormReset">
      <t-form-item label="游戏类型">
        <t-input v-model="searchForm.gameKey" placeholder="请输入游戏类型" />
      </t-form-item>
      <t-form-item>
        <t-space>
          <t-button theme="primary" type="submit">搜索</t-button>
          <t-button theme="default" variant="base" type="reset">重置</t-button>
        </t-space>
      </t-form-item>
    </t-form>

    <t-table
      :data="matchList"
      :columns="listColumns"
      row-key="id"
      vertical-align="top"
      :hover="true"
      :pagination="pagination"
      :loading="dataLoading"
      table-layout="auto"
      class="bot-match-table"
      @page-change="onPageChange"
    />
  </t-card>
</template>

<style scoped>
:deep(.dida-status-loading) {
  margin-right: 5px;
}

:deep(.bot-players-tags) {
  flex-wrap: wrap;
}

:deep(.bot-match-table .t-table__content) {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

:deep(.bot-match-table table) {
  width: max-content;
  min-width: 100%;
}

@media (max-width: 800px) {
  :deep(.bot-match-table .t-table__content) {
    max-width: 100%;
  }
}
</style>